const job = $input.first().json;
const offset = Number(job.offset ?? 0);
const limit = Number(job.limit ?? 24);
const params = new URLSearchParams();
params.set('limit', String(limit));
params.set('offset', String(offset));
params.set('sortBy', 'published_desc');
if (job.remonttityyppi) params.set('freeText', job.remonttityyppi);
if (job.current_region) params.append('locations[]', job.current_region);

return [{
  json: {
    ...job,
    oikotie_url: `https://asunnot.oikotie.fi/api/5.0/cards?${params.toString()}`,
  },
}];

const job = $('Execute Workflow Trigger').first().json;
const payload = $input.first().json;
const cards = payload.cards || payload.items || payload.data?.cards || payload.data?.items || [];
const source = job.source || 'oikotie';

const leads = cards.map((card) => {
  const cardId = card.id || card.cardId || card.card_id;
  const source_ref = `${source}-${cardId}`;
  const company = card.companyName || card.company || card.housingCompanyName || '';
  const title = card.title || card.header || card.subject || '';
  const notesParts = [
    title,
    card.description || card.text || '',
    job.remonttityyppi ? `Remonttityyppi: ${job.remonttityyppi}` : '',
    job.current_region ? `Alue: ${job.current_region}` : '',
  ].filter(Boolean);

  return {
    source_ref,
    email: `oikotie+${cardId}@noemail.flowleads.local`,
    company,
    notes: notesParts.join('\n').trim(),
    source: 'n8n',
    tags: [source, job.remonttityyppi].filter(Boolean),
    custom_fields: {
      oikotie_card_id: cardId,
      remonttityyppi: job.remonttityyppi,
      region: job.current_region,
      search_job_id: job.job_id,
      search_profile_id: job.profile_id,
    },
  };
}).filter((lead) => lead.source_ref && lead.source_ref !== `${source}-undefined`);

return [{
  json: {
    ...job,
    leads,
    leads_found: leads.length,
    source_ids: leads.map((l) => l.source_ref),
  },
}];

const job = $('Parse listings').first().json;
const dedupe = $input.first().json;
const newIds = new Set(dedupe.new_ids || []);
const newLeads = (job.leads || []).filter((lead) => newIds.has(lead.source_ref));
const duplicates = (job.leads || []).length - newLeads.length;

if (!newLeads.length) {
  return [{
    json: {
      ...job,
      lead: null,
      duplicates,
      leads_found: job.leads_found,
      has_new_lead: false,
    },
  }];
}

return newLeads.map((lead) => ({
  json: {
    ...job,
    lead,
    duplicates,
    leads_found: job.leads_found,
    has_new_lead: true,
  },
}));

const posted = $('POST lead to CRM').all();
const base = $('Filter new leads').first().json;
let leads_sent = 0;
let failed = 0;
const sentIds = [];

for (const row of posted) {
  const response = row.json || {};
  const lead = row.json?.lead || $('Filter new leads').item?.json?.lead;
  if (response.success === true || response.data) {
    leads_sent += 1;
    if (lead?.source_ref) sentIds.push(lead.source_ref);
  } else {
    failed += 1;
  }
}

return [{
  json: {
    organization_id: base.organization_id,
    source_ids_to_mark: [...new Set(sentIds)],
    leads_sent,
    failed,
    duplicates: base.duplicates || 0,
    leads_found: base.leads_found || 0,
    page: base.page,
    current_region: base.current_region,
  },
}];

const base = $('Parse listings').first().json;
const dedupe = $('Dedupe check').first().json;
const duplicates = (base.leads || []).length - (dedupe.new_ids || []).length;

return [{
  json: {
    organization_id: base.organization_id,
    source_ids_to_mark: [],
    leads_sent: 0,
    failed: 0,
    duplicates,
    leads_found: base.leads_found,
    page: base.page,
    current_region: base.current_region,
  },
}];

const summary = $('Summarize sends').first()?.json || $('No new leads summary').first()?.json || {};

return [{
  json: {
    leads_found: summary.leads_found || 0,
    leads_sent: summary.leads_sent || 0,
    duplicates: summary.duplicates || 0,
    failed: summary.failed || 0,
    page_failed: (summary.failed || 0) > 0,
    page: summary.page,
    current_region: summary.current_region,
    worker_error: summary.failed > 0 ? 'One or more leads failed to post' : '',
  },
}];
